def task_func(user, API_URL='https://api.github.com/users/'):
    url = API_URL + user + '/repos'
    repos = []
    while url:
        resp = requests.get(url)
        data = resp.json()
        if isinstance(data, list):
            repos.extend(data)
        url = None
        if 'next' in resp.links:
            url = resp.links['next']['url']
    sorted_repos = sorted(repos, key=lambda r: r['created_at'])
    return [repo['name'] for repo in sorted_repos]

