import smtplib
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = 587
EMAIL_ADDRESS = "your.email@gmail.com"
EMAIL_PASSWORD = "your.password"
def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    if input_data is None:
        return []
    try:
        parsed = json.loads(input_data)
    except:
        return []
    names = []
    recipient_email = None
    if isinstance(parsed, dict):
        if 'names' in parsed:
            names = parsed['names']
        elif 'recipients' in parsed:
            for r in parsed['recipients']:
                if isinstance(r, dict) and 'name' in r:
                    names.append(r['name'])
                if recipient_email is None and isinstance(r, dict) and 'email' in r:
                    recipient_email = r['email']
        else:
            for key, value in parsed.items():
                if isinstance(value, list):
                    for item in value:
                        if isinstance(item, dict) and 'name' in item:
                            names.append(item['name'])
        if 'recipient' in parsed:
            recipient_email = parsed['recipient']
        elif 'email' in parsed:
            recipient_email = parsed['email']
    elif isinstance(parsed, list):
        for item in parsed:
            if isinstance(item, dict):
                if 'name' in item:
                    names.append(item['name'])
                if recipient_email is None and 'email' in item:
                    recipient_email = item['email']
    if not names:
        return []
    if recipient_email is None:
        recipient_email = email_address
    message = "Subject: Extracted Names\n\n" + "\n".join(names)
    if smtp is not None:
        smtp.sendmail(email_address, recipient_email, message)
    else:
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(email_address, email_password)
        server.sendmail(email_address, recipient_email, message)
        server.quit()
    return names

import json
import smtplib
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = 587
EMAIL_ADDRESS = "your.email@gmail.com"
EMAIL_PASSWORD = "your.password"
def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    try:
        data = json.loads(input_data)
    except (json.JSONDecodeError, TypeError):
        return []
    names = []
    emails = []
    for obj in data:
        if 'name' in obj and 'email' in obj:
            names.append(obj['name'])
            emails.append(obj['email'])
    if not names:
        return []
    msg_lines = ['Subject: Extracted Names', '']
    msg_lines.extend(names)
    msg_text = '\n'.join(msg_lines)
    if smtp is None:
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(email_address, email_password)
        for to in emails:
            server.sendmail(email_address, to, msg_text)
        server.quit()
    else:
        for to in emails:
            smtp.sendmail(email_address, to, msg_text)
    return names

import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    response = requests.get(url, params=parameters, headers=HEADERS)
    if response.status_code != 200:
        raise Exception('Invalid URL or access error')
    try:
        data = response.json()
    except json.JSONDecodeError:
        raise Exception('Invalid data')
    if not data:
        raise Exception('Empty data')
    df = pd.DataFrame(data)
    if df.empty:
        raise Exception('Empty data')
    numeric_cols = df.select_dtypes(include='number').columns
    if len(numeric_cols) == 0:
        raise Exception('Invalid data')
    corr = df[numeric_cols].corr()
    ax = sns.heatmap(corr)
    return df, ax

import requests
import json
import pandas as pd
import seaborn as sns
def task_func(url, parameters):
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
    except Exception as e:
        raise Exception(f"Failed to fetch data: {e}")
    try:
        raw_data = response.json()
    except json.JSONDecodeError as e:
        raise Exception(f"Invalid JSON response: {e}")
    if not raw_data:
        raise Exception("Empty data received")
    df = pd.DataFrame(raw_data)
    if df.empty:
        raise Exception("DataFrame is empty after conversion")
    corr = df.corr(numeric_only=True)
    if corr.empty:
        raise Exception("No numeric columns to compute correlation")
    ax = sns.heatmap(corr, annot=True, cmap='coolwarm')
    return df, ax

import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        if response.status_code != 200:
            raise Exception(f"Request failed with status {response.status_code}")
        data = response.json()
        if data is None:
            raise Exception("Empty or invalid JSON response")
        if isinstance(data, list):
            df = pd.DataFrame(data)
        elif isinstance(data, dict):
            if 'data' in data:
                df = pd.DataFrame(data['data'])
            else:
                df = pd.DataFrame([data])
        else:
            raise Exception("Unexpected data format")
        if df.empty:
            raise Exception("No data in response")
        numeric_df = df.select_dtypes(include='number')
        if numeric_df.empty:
            raise Exception("No numerical columns to correlate")
        corr = numeric_df.corr()
        ax = sns.heatmap(corr, annot=True, cmap='coolwarm')
        return df, ax
    except Exception as e:
        raise Exception(str(e))

