                    text = data.get('text', '')
                    words.extend(text.lower().split())
                except (json.JSONDecodeError, AttributeError):
                    continue
    cleaned_words = []
    for w in words:
        cleaned = ''.join(c for c in w if c.isalnum() or c.isspace()).strip()
        if cleaned:
            cleaned_words.append(cleaned)
    counter = Counter(cleaned_words)
    return counter.most_common(word_count)

