            raise ValueError("Non-numeric population")
        if pop < 0:
            raise ValueError("Negative population")
        if isinstance(pop, float):
            pop = int(math.floor(pop))
        countries.append(country)
        populations.append(pop)
    df = pd.DataFrame({"Country": countries, "Population": populations})
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except (OSError, IOError):
        raise IOError(f"Cannot write file to {file_path}")
    return os.path.abspath(file_path), df

import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
import yaml
def task_func(json_data: str, key_path: list):
    if not json_data:
        raise ValueError("Data string is empty")
    try:
        tempload = lambda t: yaml.load(t, Loader=yaml.Loader)
        data = tempload(json_data)
    except Exception:
        raise ValueError("Data string is corrupted")
    current = data
    for key in key_path:
        if key not in current:
            raise KeyError(f"Key '{key}' not found")
        current = current[key]
    if isinstance(current, (int, float, np.floating, np.integer)):
        values = [float(current)]
    elif isinstance(current, list):
        values = [float(v) for v in current if isinstance(v, (int, float, np.floating, np.integer))]
    else:
        values = []
    if not values:
        raise ValueError("No numeric data found")
    fig, ax = plt.subplots()
    ax.boxplot(values)
    return fig

def task_func(json_data: str, key_path: list):
    import json
    import numpy as np
    import matplotlib.pyplot as plt
    import seaborn as sns
    import pandas as pd

    data = json.loads(json_data)
    current = data
    for key in key_path:
        if not isinstance(current, dict) or key not in current:
            raise KeyError(f"Key '{key}' not found in JSON structure")
        current = current[key]

    if isinstance(current, str):
        tokens = current.replace(',', ' ').split()
        values = []
        for tok in tokens:
            tok = tok.strip()
            if tok:
                try:
                    values.append(float(tok))
                except ValueError:
                    raise ValueError("Non-numeric data found in the string")
        if not values:
            raise ValueError("No numeric data found, or data string is empty")
    elif isinstance(current, list):
        values = []
        for item in current:
            try:
                values.append(float(item))
            except (ValueError, TypeError):
                raise ValueError("Non-numeric data found in the list")
        if not values:
            raise ValueError("No numeric data found in the list")
    else:
        raise ValueError("Data is not a string or list")

    fig, ax = plt.subplots()
    sns.boxplot(data=values, ax=ax)
